def calculate_b_squared(a):
    # Check for division by zero
    if a == 2:
        return None, "Undefined (a=2)"

    # Calculate b^2 = a^2 - a / (a - 2)
    b_squared = a**2 - (a / (a - 2))
    return b_squared, None

test_a = [0, 1, 3, 4, -1, -2]
results = {}

for a in test_a:
    b_sq, error = calculate_b_squared(a)
    results[a] = b_sq

print("--- Results for b^2 ---")
for a, b_sq in results.items():
    print(f"a = {a}: b^2 = {b_sq}")

